def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_bp(n):
        bp = []
        for _ in range(n):
            bp.append(random.choice([0, 1]))
        return bp

    def construct_quadratic_form(bp):
        n = len(bp)
        Q = [[0] * n for _ in range(n)]

        for i in range(n):
            for j in range(i, n):
                if bp[i] == bp[j]:
                    Q[i][j] = 1
                    Q[j][i] = 1

        return Q

    def determinant(matrix):
        n = len(matrix)
        if n == 1:
            return matrix[0][0]

        det = 0
        for j in range(n):
            submatrix = [row[:j] + row[j+1:] for row in matrix[1:]]
            det += (-1) ** j * matrix[0][j] * determinant(submatrix)

        return det

    def min_rank(matrix):
        n = len(matrix)
        rank = 0

        for i in range(n):
            if all(matrix[j][i] == 0 for j in range(i, n)):
                continue
            pivot_row = i
            while matrix[pivot_row][i] == 0:
                pivot_row += 1
                if pivot_row == n:
                    return rank
            matrix[i], matrix[pivot_row] = matrix[pivot_row], matrix[i]
            for j in range(n):
                if j != i:
                    factor = Fraction(matrix[j][i], matrix[i][i])
                    for k in range(n):
                        matrix[j][k] -= factor * matrix[i][k]
            rank += 1

        return rank

    def bp_size(bp):
        return sum(bp)

    n_values = [5, 10, 15, 20, 30, 40]
    results = []

    for n in n_values:
        bp = generate_bp(n)
        Q = construct_quadratic_form(bp)
        rank = min_rank(Q)
        size = bp_size(bp)

        if rank == 0 or size == 0:
            continue

